function kidsWithEight(money: number, children: number): number {
  if (money < children) return -1;
  for (let k = Math.min(children, Math.floor(money / 8)); k >= 0; k--) {
    const rest = money - 8 * k, others = children - k;
    if (others === 0) { if (rest === 0) return k; continue; }
    if (rest < others) continue;     // someone would get 0
    if (others === 1 && rest === 4) continue; // the single other kid gets 4
    return k;
  }
  return 0;
}

