class Solution:
    def kidsWithEight(self, money: int, children: int) -> int:
        if money < children:
            return -1
        for k in range(min(children, money // 8), -1, -1):
            rest, others = money - 8 * k, children - k
            if others == 0:
                if rest == 0:
                    return k
                continue
            if rest < others or (others == 1 and rest == 4):
                continue
            return k
        return 0

