function kidsWithEight(money: number, children: number): number {
  if (money < children) return -1;
  const rest = money - children;
  const k = Math.min(children, Math.floor(rest / 7));
  if (k === children && rest > 7 * children) return children - 1;
  if (k === children - 1 && rest - 7 * k === 3) return k - 1;
  return k;
}

